3412 bool LoopVectorizationCostModel::interleavedAccessCanBeWidened(
3413     Instruction *I, ElementCount VF) const {
3414   assert(isAccessInterleaved(I) && "Expecting interleaved access.");
3415   assert(getWideningDecision(I, VF) == CM_Unknown &&
3416          "Decision should not be set yet.");
3417   auto *Group = getInterleavedAccessGroup(I);
3418   assert(Group && "Must have a group.");
3419 
3420   // If the instruction's allocated size doesn't equal it's type size, it
3421   // requires padding and will be scalarized.
3422   auto &DL = I->getDataLayout();
3423   auto *ScalarTy = getLoadStoreType(I);
3424   if (hasIrregularType(ScalarTy, DL))
3425     return false;
3426 
3427   // If the group involves a non-integral pointer, we may not be able to
3428   // losslessly cast all values to a common type.
3429   unsigned InterleaveFactor = Group->getFactor();
3430   bool ScalarNI = DL.isNonIntegralPointerType(ScalarTy);
3431   for (unsigned Idx = 0; Idx < InterleaveFactor; Idx++) {
3432     Instruction *Member = Group->getMember(Idx);
3433     if (!Member)
3434       continue;
3435     auto *MemberTy = getLoadStoreType(Member);
3436     bool MemberNI = DL.isNonIntegralPointerType(MemberTy);
3437     // Don't coerce non-integral pointers to integers or vice versa.
3438     if (MemberNI != ScalarNI)
3439       // TODO: Consider adding special nullptr value case here
3440       return false;
3441     if (MemberNI && ScalarNI &&
3442         ScalarTy->getPointerAddressSpace() !=
3443             MemberTy->getPointerAddressSpace())
3444       return false;
3445   }
3446 
3447   // Check if masking is required.
3448   // A Group may need masking for one of two reasons: it resides in a block that
3449   // needs predication, or it was decided to use masking to deal with gaps
3450   // (either a gap at the end of a load-access that may result in a speculative
3451   // load, or any gaps in a store-access).
3452   bool PredicatedAccessRequiresMasking =
3453       blockNeedsPredicationForAnyReason(I->getParent()) &&
3454       Legal->isMaskRequired(I);
3455   bool LoadAccessWithGapsRequiresEpilogMasking =
3456       isa<LoadInst>(I) && Group->requiresScalarEpilogue() &&
3457       !isScalarEpilogueAllowed();
3458   bool StoreAccessWithGapsRequiresMasking =
3459       isa<StoreInst>(I) && (Group->getNumMembers() < Group->getFactor());
3460   if (!PredicatedAccessRequiresMasking &&
3461       !LoadAccessWithGapsRequiresEpilogMasking &&
3462       !StoreAccessWithGapsRequiresMasking)
3463     return true;
3464 
3465   // If masked interleaving is required, we expect that the user/target had
3466   // enabled it, because otherwise it either wouldn't have been created or
3467   // it should have been invalidated by the CostModel.
3468   assert(useMaskedInterleavedAccesses(TTI) &&
3469          "Masked interleave-groups for predicated accesses are not enabled.");
3470 
3471   if (Group->isReverse())
3472     return false;
3473 
3474   auto *Ty = getLoadStoreType(I);
3475   const Align Alignment = getLoadStoreAlignment(I);
3476   return isa<LoadInst>(I) ? TTI.isLegalMaskedLoad(Ty, Alignment)
3477                           : TTI.isLegalMaskedStore(Ty, Alignment);
3478 }
