 861   // Check for a splat of a constant or for a non uniform vector of constants
 862   // and check if the constant(s) are all powers of two.
 863   if (isa<ConstantVector>(V) || isa<ConstantDataVector>(V)) {
 864     OpInfo = OK_NonUniformConstantValue;
 865     if (Splat) {
 866       OpInfo = OK_UniformConstantValue;
 867       if (auto *CI = dyn_cast<ConstantInt>(Splat)) {
 868         if (CI->getValue().isPowerOf2())
 869           OpProps = OP_PowerOf2;
 870         else if (CI->getValue().isNegatedPowerOf2())
 871           OpProps = OP_NegatedPowerOf2;
 872       }
 873     } else if (const auto *CDS = dyn_cast<ConstantDataSequential>(V)) {
 874       bool AllPow2 = true, AllNegPow2 = true;
 875       for (unsigned I = 0, E = CDS->getNumElements(); I != E; ++I) {
 876         if (auto *CI = dyn_cast<ConstantInt>(CDS->getElementAsConstant(I))) {
 877           AllPow2 &= CI->getValue().isPowerOf2();
 878           AllNegPow2 &= CI->getValue().isNegatedPowerOf2();
 879           if (AllPow2 || AllNegPow2)
 880             continue;
 881         }
 882         AllPow2 = AllNegPow2 = false;
 883         break;
 884       }
