3358   InstructionCost ScalarizationCost = InstructionCost::getInvalid();
3359   if (!VF.isScalable()) {
3360     // Get the scalarization cost and scale this amount by the probability of
3361     // executing the predicated block. If the instruction is not predicated,
3362     // we fall through to the next case.
3363     ScalarizationCost = 0;
3364 
3365     // These instructions have a non-void type, so account for the phi nodes
3366     // that we will create. This cost is likely to be zero. The phi node
3367     // cost, if any, should be scaled by the block probability because it
3368     // models a copy at the end of each predicated block.
3369     ScalarizationCost += VF.getKnownMinValue() *
3370       TTI.getCFInstrCost(Instruction::PHI, CostKind);
3371 
3372     // The cost of the non-predicated instruction.
3373     ScalarizationCost += VF.getKnownMinValue() *
3374       TTI.getArithmeticInstrCost(I->getOpcode(), I->getType(), CostKind);
3375 
3376     // The cost of insertelement and extractelement instructions needed for
3377     // scalarization.
3378     ScalarizationCost += getScalarizationOverhead(I, VF, CostKind);
3379 
3380     // Scale the cost by the probability of executing the predicated blocks.
3381     // This assumes the predicated block for each vector lane is equally
