3480 bool LoopVectorizationCostModel::memoryInstructionCanBeWidened(
3481     Instruction *I, ElementCount VF) {
3482   // Get and ensure we have a valid memory instruction.
3483   assert((isa<LoadInst, StoreInst>(I)) && "Invalid memory instruction");
3484 
3485   auto *Ptr = getLoadStorePointerOperand(I);
3486   auto *ScalarTy = getLoadStoreType(I);
3487 
3488   // In order to be widened, the pointer should be consecutive, first of all.
3489   if (!Legal->isConsecutivePtr(ScalarTy, Ptr))
3490     return false;
3491 
3492   // If the instruction is a store located in a predicated block, it will be
3493   // scalarized.
3494   if (isScalarWithPredication(I, VF))
3495     return false;
3496 
3497   // If the instruction's allocated size doesn't equal it's type size, it
3498   // requires padding and will be scalarized.
3499   auto &DL = I->getDataLayout();
3500   if (hasIrregularType(ScalarTy, DL))
3501     return false;
3502 
3503   return true;
3504 }
