3506 void LoopVectorizationCostModel::collectLoopUniforms(ElementCount VF) {
3507   // We should not collect Uniforms more than once per VF. Right now,
3508   // this function is called from collectUniformsAndScalars(), which
3509   // already does this check. Collecting Uniforms for VF=1 does not make any
3510   // sense.
3511 
3512   assert(VF.isVector() && !Uniforms.contains(VF) &&
3513          "This function should not be visited twice for the same VF");
3514 
3515   // Visit the list of Uniforms. If we'll not find any uniform value, we'll
3516   // not analyze again.  Uniforms.count(VF) will return 1.
3517   Uniforms[VF].clear();
3518 
3519   // We now know that the loop is vectorizable!
3520   // Collect instructions inside the loop that will remain uniform after
3521   // vectorization.
3522 
3523   // Global values, params and instructions outside of current loop are out of
3524   // scope.
3525   auto IsOutOfScope = [&](Value *V) -> bool {
3526     Instruction *I = dyn_cast<Instruction>(V);
3527     return (!I || !TheLoop->contains(I));
3528   };
3529 
3530   // Worklist containing uniform instructions demanding lane 0.
3531   SetVector<Instruction *> Worklist;
3532 
3533   // Add uniform instructions demanding lane 0 to the worklist. Instructions
3534   // that require predication must not be considered uniform after
3535   // vectorization, because that would create an erroneous replicating region
3536   // where only a single instance out of VF should be formed.
3537   auto AddToWorklistIfAllowed = [&](Instruction *I) -> void {
3538     if (IsOutOfScope(I)) {
3539       LLVM_DEBUG(dbgs() << "LV: Found not uniform due to scope: "
3540                         << *I << "\n");
3541       return;
3542     }
3543     if (isPredicatedInst(I)) {
3544       LLVM_DEBUG(
3545           dbgs() << "LV: Found not uniform due to requiring predication: " << *I
3546                  << "\n");
3547       return;
3548     }
3549     LLVM_DEBUG(dbgs() << "LV: Found uniform instruction: " << *I << "\n");
3550     Worklist.insert(I);
3551   };
3552 
3553   // Start with the conditional branches exiting the loop. If the branch
3554   // condition is an instruction contained in the loop that is only used by the
3555   // branch, it is uniform.
3556   SmallVector<BasicBlock *> Exiting;
3557   TheLoop->getExitingBlocks(Exiting);
3558   for (BasicBlock *E : Exiting) {
3559     auto *Cmp = dyn_cast<Instruction>(E->getTerminator()->getOperand(0));
3560     if (Cmp && TheLoop->contains(Cmp) && Cmp->hasOneUse())
3561       AddToWorklistIfAllowed(Cmp);
3562   }
3563 
3564   auto PrevVF = VF.divideCoefficientBy(2);
3565   // Return true if all lanes perform the same memory operation, and we can
3566   // thus chose to execute only one.
3567   auto IsUniformMemOpUse = [&](Instruction *I) {
3568     // If the value was already known to not be uniform for the previous
3569     // (smaller VF), it cannot be uniform for the larger VF.
3570     if (PrevVF.isVector()) {
3571       auto Iter = Uniforms.find(PrevVF);
3572       if (Iter != Uniforms.end() && !Iter->second.contains(I))
3573         return false;
3574     }
3575     if (!Legal->isUniformMemOp(*I, VF))
3576       return false;
3577     if (isa<LoadInst>(I))
3578       // Loading the same address always produces the same result - at least
3579       // assuming aliasing and ordering which have already been checked.
3580       return true;
3581     // Storing the same value on every iteration.
3582     return TheLoop->isLoopInvariant(cast<StoreInst>(I)->getValueOperand());
3583   };
3584 
3585   auto IsUniformDecision = [&](Instruction *I, ElementCount VF) {
3586     InstWidening WideningDecision = getWideningDecision(I, VF);
3587     assert(WideningDecision != CM_Unknown &&
3588            "Widening decision should be ready at this moment");
3589 
